		flags:        map[string]*flipt.Flag{},
		segments:     map[string]*flipt.Segment{},
		rules:        map[string]*flipt.Rule{},
		rollouts:     map[string]*flipt.Rollout{},
		evalRules:    map[string][]*storage.EvaluationRule{},
		evalRollouts: map[string][]*storage.EvaluationRollout{},
	}
}

// SnapshotFromFS discovers state files and builds a validated snapshot.
func SnapshotFromFS(logger *zap.Logger, source fs.FS) (*StoreSnapshot, error) {
	files, err := listStateFiles(logger, source)
	if err != nil {
		return nil, err
	}

	logger.Debug("opening state files", zap.Strings("paths", files))
	return SnapshotFromPaths(source, files...)
}

// SnapshotFromPaths builds a snapshot from explicit paths in source.
// All files are validated before any are assembled into the snapshot.
func SnapshotFromPaths(source fs.FS, paths ...string) (*StoreSnapshot, error) {
	validator, err := cue.NewFeaturesValidator()
	if err != nil {
		return nil, err
	}
	var readers []io.Reader
	for _, file := range paths {
		b, err := fs.ReadFile(source, file)
		if err != nil {
			return nil, err
		}
		if err := validator.Validate(file, b); err != nil {
			return nil, err
		}
		readers = append(readers, bytes.NewReader(b))
	}
	return snapshotFromReaders(readers...)
}

// snapshotFromReaders constructs a StoreSnapshot from the provided
// slice of io.Reader.
func snapshotFromReaders(sources ...io.Reader) (*StoreSnapshot, error) {
	now := timestamppb.Now()
	s := StoreSnapshot{
		ns: map[string]*namespace{
			defaultNs: newNamespace("default", "Default", now),
		},
		evalDists: map[string][]*storage.EvaluationDistribution{},
		now:       now,
	}

	for _, reader := range sources {
		doc := new(ext.Document)

		if err := yaml.NewDecoder(reader).Decode(doc); err != nil {
			return nil, err
		}

		// set namespace to default if empty in document
		if doc.Namespace == "" {
			doc.Namespace = "default"
		}

		if err := s.addDoc(doc); err != nil {
			return nil, err
		}

	}
	return &s, nil
}

