package cue

import (
	_ "embed"
	"errors"
	"fmt"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerrors "cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
	yamlv3 "gopkg.in/yaml.v3"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error is a collection of fields that represent positions in files where the user
// has made some kind of error.
type Error struct {
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

func (e Error) Error() string {
	return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column)
}

// Result is a collection of errors that occurred during validation.
type Result struct {
	Errors []Error `json:"errors"`
}

type validationErrors []error

func (e validationErrors) Error() string        { return ErrValidationFailed.Error() }
func (e validationErrors) Unwrap() []error      { return []error(e) }
func (e validationErrors) Is(target error) bool { return target == ErrValidationFailed }

// Unwrap returns the individual errors in a validation failure.
func Unwrap(err error) ([]error, bool) {
	var multi interface{ Unwrap() []error }
	if errors.As(err, &multi) {
		return multi.Unwrap(), true
	}
	return nil, false
}

type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil {
		return nil, v.Err()
	}

	return &FeaturesValidator{
		cue: cctx,
		v:   v,
	}, nil
}

// Validate validates a YAML file against our cue definition of features.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	f, err := yaml.Extract(file, b)
	if err != nil {
		return err
	}

	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil {
		return err
	}

	err = v.v.
		Unify(yv).
		Validate(cue.All(), cue.Concrete(true))

	var problems validationErrors
	for _, e := range cueerrors.Errors(err) {
		rerr := Error{
			Message: e.Error(),
			Location: Location{
				File: file,
			},
		}

		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			rerr.Location.Line = p.Line()
			rerr.Location.Column = p.Column()
		}

		problems = append(problems, rerr)
	}

	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil {
		return err
	}
	if len(root.Content) > 0 {
		problems = append(problems, referenceErrors(file, root.Content[0])...)
	}
	if len(problems) > 0 {
		return problems
	}
	return nil
}

func field(node *yamlv3.Node, key string) *yamlv3.Node {
	if node == nil || node.Kind != yamlv3.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(node.Content); i += 2 {
		if node.Content[i].Value == key {
			return node.Content[i+1]
		}
	}
	return nil
}

func items(node *yamlv3.Node) []*yamlv3.Node {
	if node != nil && node.Kind == yamlv3.SequenceNode {
		return node.Content
	}
	return nil
}

func value(node *yamlv3.Node) string {
	if node != nil {
		return node.Value
	}
	return ""
}

func referenceErrors(file string, root *yamlv3.Node) []error {
	namespace := value(field(root, "namespace"))
	if namespace == "" {
		namespace = "default"
	}
	segments := map[string]bool{}
	for _, segment := range items(field(root, "segments")) {
		segments[value(field(segment, "key"))] = true
	}
	var problems []error
	add := func(message string, node *yamlv3.Node) {
		if node != nil {
			problems = append(problems, Error{Message: message, Location: Location{File: file, Line: node.Line, Column: node.Column}})
		}
	}
	checkSegment := func(prefix string, node *yamlv3.Node) {
		if node == nil {
			return
		}
		if node.Kind == yamlv3.ScalarNode {
			if !segments[node.Value] {
				add(fmt.Sprintf("%s references unknown segment %q", prefix, node.Value), node)
			}
			return
		}
		if key := field(node, "key"); key != nil && !segments[key.Value] {
			add(fmt.Sprintf("%s references unknown segment %q", prefix, key.Value), key)
		}
		for _, key := range items(field(node, "keys")) {
			if !segments[key.Value] {
				add(fmt.Sprintf("%s references unknown segment %q", prefix, key.Value), key)
			}
		}
	}
	for _, flag := range items(field(root, "flags")) {
		prefix := fmt.Sprintf("flag %s/%s", namespace, value(field(flag, "key")))
		variants := map[string]bool{}
		for _, variant := range items(field(flag, "variants")) {
			variants[value(field(variant, "key"))] = true
		}
		for i, rule := range items(field(flag, "rules")) {
			rulePrefix := fmt.Sprintf("%s rule %d", prefix, i+1)
			checkSegment(rulePrefix, field(rule, "segment"))
			for _, distribution := range items(field(rule, "distributions")) {
				variant := field(distribution, "variant")
				if variant != nil && !variants[variant.Value] {
					add(fmt.Sprintf("%s references unknown variant %q", rulePrefix, variant.Value), variant)
				}
			}
		}
		for i, rollout := range items(field(flag, "rollouts")) {
			checkSegment(fmt.Sprintf("%s rollout %d", prefix, i+1), field(rollout, "segment"))
		}
	}
	return problems
}

